505 static bool processAbsIntrinsic(IntrinsicInst *II, LazyValueInfo *LVI) {
506   Value *X = II->getArgOperand(0);
507   Type *Ty = X->getType();
508   if (!Ty->isIntegerTy())
509     return false;
510 
511   bool IsIntMinPoison = cast<ConstantInt>(II->getArgOperand(1))->isOne();
512   APInt IntMin = APInt::getSignedMinValue(Ty->getScalarSizeInBits());
513   ConstantRange Range = LVI->getConstantRangeAtUse(
514       II->getOperandUse(0), /*UndefAllowed*/ IsIntMinPoison);
